function.arguments:
{"content": "{
  "main_characters": [
    {
      "name": "沈瓷",
      "role": "protagonist",
      "identity": "古董鉴定师，出身文物修复世家，前豪门儿媳",
      "traits": ["专业执拗", "外柔内刚", "社交笨拙", "敏锐细腻", "倔强隐忍"],
      "overt_motivation": "把离婚得到的那箱古董变现，在古董行站稳脚跟，建立自己的鉴定事业",
      "covert_motivation": "证明自己不只是某个豪门的前儿媳——她的专业值得被尊重，她这个人值得被当回事",
      "secret_fear": "害怕自己在豪门三年的妥协已经磨掉了专业锐气，害怕有一天发现自己看走眼不是意外而是退步的开始",
      "misperception_of_other": "初期认为陆征野是古董行里又一个只看钱不懂货的掮客",
      "hidden_connection": "她外公纪守真三十年前修复的那批永乐官窑残件，与方鸿儒当年的一桩旧案有关"
    },
    {
      "name": "陆征野",
      "role": "deuteragonist",
      "identity": "独立古董经纪人/买手，精通市场运作但非学院派",
      "traits": ["市侩精明", "直觉敏锐", "信守承诺", "表面轻浮", "内心有底线"],
      "overt_motivation": "做成大单子，在古董经纪行业建立自己的品牌",
      "covert_motivation": "摆脱父亲'赝品贩子'的家族阴影，证明自己赚的是干净钱",
      "secret_fear": "害怕自己某天为了利益越过底线，变成父亲那样的人",
      "misperception_of_other": "初期认为沈瓷是豪门里养出来的花瓶，靠家世混鉴定圈",
      "hidden_connection": "他父亲当年卖出的一批赝品，其中有一件就是仿的永乐官窑——仿品的底本来自方鸿儒提供的资料"
    }
  ],
  "supporting_characters": [
    {
      "name": "纪守真",
      "function": "助力",
      "identity": "沈瓷的外公，故宫退休陶瓷修复师，八十多岁",
      "description": "沈瓷专业能力的根源。年事已高但记忆清晰，对经手的每一件瓷器如数家珍。不直接参与古董交易，但在关键时刻提供决定性的专业判断。他的修复笔记是沈瓷最重要的武器，但他本人对孙女涉足古董江湖充满担忧——因为他知道这行有多脏。"
    },
    {
      "name": "方鸿儒",
      "function": "反转点",
      "identity": "资深古董鉴定师，行业权威，六十多岁",
      "description": "表面是德高望重的行业前辈，初期对沈瓷表现出提携之意。实际上三十年前他与陆征野父亲有过一桩见不得光的交易——他提供真品资料帮人造高仿，事后为了洗白自己，把罪名全推给了陆征野的父亲。沈瓷手里的永乐官窑青花罐一旦曝光，可能牵出这段旧事。他的提携背后是试探和控制。"
    },
    {
      "name": "裴昱庭",
      "function": "阻碍",
      "identity": "沈瓷的前夫，裴家长子，地产公司副总",
      "description": "不算坏人但极度软弱。离婚时并不知道那箱东西的真实价值，是母亲钟惠兰发现后逼他走法律途径追讨。他内心对沈瓷有愧疚，但在家族利益面前永远选择服从。在法律战中是母亲的提线木偶，偶尔的善意举动反而让沈瓷的处境更复杂——因为对方律师会利用这些'善意'做文章。"
    },
    {
      "name": "钟惠兰",
      "function": "阻碍",
      "identity": "沈瓷的前婆婆，裴家实际掌控者",
      "description": "精明强势的豪门女主人。当初选中沈瓷就是看中她文物世家的背景，想让她帮家族打理收藏——但骨子里从未把沈瓷当自家人。发现那箱'破烂'里有国宝级藏品后震怒，认为沈瓷蓄意欺骗，动用家族律师团和行业人脉双线施压。她的可怕之处在于不动声色——不会撕破脸，而是在每一个关键环节设置障碍。"
    },
    {
      "name": "谢檀",
      "function": "助力",
      "identity": "青年律师，后成为沈瓷的法律顾问和合伙人",
      "description": "精干利落，对文物法律法规有专攻。她主动找到沈瓷不是出于同情，而是看到了古董法律纠纷这个细分市场的商业前景。她帮沈瓷打赢法律战的同时也在建立自己的专业品牌。两人是互利的合作关系，不是单方面的施恩。谢檀有自己的野心和判断，偶尔会和沈瓷产生策略分歧。"
    },
    {
      "name": "贾茂生",
      "function": "阻碍",
      "identity": "古董贩子，高仿专家，五十多岁",
      "description": "古董行里的'技术流'——不偷不抢，靠高仿赚钱。手艺精湛到连部分行家都看不出。他跟方鸿儒有旧交情，跟裴家有生意往来。沈瓷第一次被坑就是栽在他手上——他用一件精仿的成化斗彩杯设局，几乎毁掉沈瓷刚建立的鉴定信誉。他不是纯粹的反派，有自己的生存哲学：'这行里谁的手干净？'"
    },
    {
      "name": "温岱",
      "function": "助力",
      "identity": "文物修复师，沈瓷外公的关门弟子，三十多岁",
      "description": "继承了纪守真的修复手艺，性格沉默寡言但技术扎实。他是沈瓷在专业领域最可靠的支撑——当她需要从修复角度验证一件器物的年代时，温岱是唯一能帮她的人。但他有自己的困境：修复师收入微薄，他一直在犹豫是否接贾茂生的'修旧如旧'私活来补贴生计。这个选择最终把他推向了沈瓷和贾茂生之间的夹缝。"
    }
  ],
  "relationship_dynamics": "【核心关系网】\n\n一、沈瓷 ↔ 陆征野（从互相看不起到势均力敌的合作/暧昧）：\n初始状态：互相轻视——沈瓷觉得他是只会炒价的掮客，陆征野觉得她是豪门花瓶。第一次合作（第3章）因理念冲突不欢而散。中期因共同对抗裴家和方鸿儒而被迫合作，逐渐发现对方的专业价值——沈瓷发现陆征野对市场的嗅觉能弥补她的商业短板，陆征野发现沈瓷的学术功底是他最缺的东西。感情线埋在专业互补里，不是谁救谁，而是各凭本事后的互相欣赏。直到发现各自家族与方鸿儒旧案的关联后，信任面临考验——陆征野的父亲当年的赝品生意，与沈瓷外公修复的那批残件有牵连。关系转折点与第二幕turning_point呼应。\n\n二、沈瓷 ↔ 方鸿儒（从崇拜到识破的师徒假象）：\n初始状态：沈瓷视方鸿儒为行业权威，方鸿儒主动示好。中期方鸿儒推荐沈瓷进入高端鉴定圈，看似提携实为监控。当沈瓷的永乐青花罐即将公开鉴定时，方鸿儒开始暗中施压——通过学术质疑动摇沈瓷的鉴定结论。沈瓷逐渐发现方鸿儒的'好意'背后是恐惧：他怕旧事被翻出来。关系在第三幕公开鉴定会上彻底摊牌。\n\n三、沈瓷 ↔ 裴家（法律攻防线）：\n初始状态：离婚协议已签，看似了断。钟惠兰发现藏品价值后，通过裴昱庭发起法律追讨（主张离婚时存在欺诈/重大误解）。谢檀帮沈瓷进行法律防御。法律线与商业线交叉：裴家律师团试图冻结沈瓷的藏品，阻止她出售变现；钟惠兰动用行业人脉联合压价。裴昱庭在中间摇摆，偶尔的'善意'反而被律师利用。\n\n四、陆征野 ↔ 方鸿儒（仇恨与利益的纠缠）：\n陆征野一直在追查毁掉父亲名誉的真凶。他隐约知道方鸿儒有嫌疑但没有证据。与沈瓷合作后，通过永乐青花罐的溯源，逐渐拼出真相。这条线在第二幕后期与沈瓷的鉴定线合流。\n\n五、温岱的夹缝困境：\n温岱作为纪守真的弟子，是沈瓷天然的盟友。但贾茂生用高薪诱惑他做'修旧如旧'（本质是帮赝品做旧），温岱在经济压力下动摇。这个选择在中期制造了沈瓷阵营内部的裂痕——当沈瓷发现温岱帮贾茂生做过活，她面临信任危机：温岱的修复鉴定还能信吗？\n\n【关系转折与大纲呼应】\n第一幕转折点（沈瓷被贾茂生设局坑了信誉）→ 逼迫沈瓷必须找到行业盟友 → 与陆征野、方鸿儒的关系进入新阶段\n第二幕转折点（发现方鸿儒与三十年前赝品案的关联）→ 沈瓷与陆征野的关系面临考验（各自家族的牵连），沈瓷与方鸿儒的关系从信任到对抗"
}
